  if (tok === '<' || tok === '>' || tok === '>>' || tok === '&>' || tok === '&>>') {
    return true;
  }
  if (/^&>/.test(tok)) return true;
  if (/^(?:\d*)>{1,2}/.test(tok)) return true;
  if (/^(?:\d*)(?:<<|<>|<&|<)/.test(tok)) return true;
  return false;
